{
  "name": "opencode-tui-image-clipboard-fix",
  "version": "1.0.17",
  "type": "module",
  "displayName": "Image Clipboard Fix",
  "description": "OpenCode TUI plugin to fix image paste issues - saves clipboard images locally and replaces [Image N] with file paths",
  "main": "lib/index.js",
  "types": "lib/index.d.ts",
  "exports": {
    ".": {
      "types": "./lib/index.d.ts",
      "import": "./lib/index.js",
      "require": "./lib/index.js"
    }
  },
  "files": [
    "lib",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "clean": "rm -rf lib",
    "prepublishOnly": "npm run clean && npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "image",
    "storage",
    "base64",
    "clipboard",
    "paste",
    "drag-drop",
    "ai",
    "llm"
  ],
  "author": "chanliang",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/chanliang/opencode-tui-image-clipboard-fix.git"
  },
  "bugs": {
    "url": "https://github.com/chanliang/opencode-tui-image-clipboard-fix/issues"
  },
  "homepage": "https://github.com/chanliang/opencode-tui-image-clipboard-fix#readme",
  "engines": {
    "node": ">=18.0.0"
  },
  "devDependencies": {
    "@types/node": "^20.0.0",
    "typescript": "^5.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  }
}
